arguments.bulk_insert_payload:
{% set api_calls = [] %}{% for field in vars.lookup_fields_needed
%}{% set json = {
            "ownsRelationship": false,
            "visibility": true,
            "writeable": true,
            "gridColumn": false,
            "defaultValue": None,
            "bulkAction": {
                "allow": false,
                "buttonText": "",
                "buttonIcon": "",
                "buttonClass": "btn btn-default btn-sm"
            },
            "validation": {
                "required": false,
                "minlength": 0,
                "maxlength": 10485761
            },
            "name": vars.new_module_metadata.type,
            "descriptions": {
                "singular": vars.new_module_name
            },
            "formType": "lookup",
            "type": vars.new_module_metadata.type,
            "orderIndex": 1,
            "dataType": "lookup",
            "title": "Lookup (One to Many or One to One)",
            "dataSource": {
                "model": vars.new_module_metadata.type
            },
            "usable": true,
            "searchable": false,
            "lengthConstraint": false,
            "playbookField": true,
            "collection": false,
            "encrypted": false,
            "displayName": "{{{{ {} }}}}".format(vars.new_module_metadata.type),
            "sattrib": "/api/3/staging_model_metadatas/{}".format(field.origin_module_uuid)
        }%}
{%- do api_calls.append(json)-%}{%endfor%}{ "data": {{api_calls}} }

arguments.new_module_templates:
{% set templates = vars.steps.Get_Old_Module_View_Templates.data['hydra:member'] %}
{% for template in templates%}
{% do template.update({"uuid": template.uuid | replace(vars.old_module_tablename, vars.new_module_metadata.type)})%}
{% do template.pop("@id")%}
{%endfor%}
{{(templates | string | replace("'resource': '{}'".format(vars.old_module_tablename), "'resource': '{}'".format(vars.new_module_metadata.type)) | replace("'module': '{}'".format(vars.old_module_tablename), "'module': '{}'".format(vars.new_module_metadata.type))) | toDict}}

arguments.staging_module_schema:
{%- set staging_schema = vars.old_module_schema | replace(vars.old_module_uuid, vars.new_module_uuid) | toDict -%}
{%- do staging_schema.update({"type": vars.new_module_metadata.type, "tableName": vars.new_module_metadata.type, "module": vars.new_module_metadata.type, "descriptions": {"singular": vars.new_module_metadata.singular, "plural": vars.new_module_metadata.plural}}) -%}
{%- do staging_schema.pop('@id') -%}

{%- set uniqueness = ( staging_schema | json_query('uniqueConstraint[].*[]') |first) -%}
{%- set unique_columns= {(vars.new_module_metadata.type + "_unique") : uniqueness} -%}
{%- do staging_schema.update({ "uniqueConstraint": [unique_columns] }) -%}

{%- for attribute in staging_schema['attributes'] -%}
	{%- do attribute.pop('inversedField') -%}
    {%- do attribute.pop('uuid') -%}
    {%- do attribute.pop('@id') -%}
    {%- do attribute.update({"sattrib": ("/api/3/staging_model_metadatas/" + vars.new_module_uuid )}) -%}

	{%- if attribute.formType == "manyToMany"-%}
		{%- do attribute.update({"dataType": "manyToMany", "displayTemplate": "{{title}}",  "isNew": true, "mmdUpdate": true, "title": "Many to Many",  "usable": true }) -%}
	{%- elif attribute.formType == "oneToMany"-%}
    	{%- do attribute.update({"dataType": "oneToMany",  "isNew": true, "mmdUpdate": true, "title": "Many to One",  "usable": true, "bulkAction": {} }) -%}
        {%- do staging_schema.update({"_changed": true}) -%}
	{%- endif -%}

{%- endfor -%}
{{staging_schema}}
